def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = resp.get("limit", 0) or 0

    # Network rule: self_employed with requested_limit > 6000 -> manual review
    # (unless it was already a decline, which stays a decline)
    if (app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 6000):
        if decision == "decline":
            return {"action": "decline", "limit": 0}
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "refer":
        return {"action": "queue_review", "limit": 0}
    # decline
    return {"action": "decline", "limit": 0}
